import { LibraryError } from './libraryErrors';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { randomUUID } from 'crypto';
import { z } from 'zod';
import { ProjectRecords } from '../storage/library/ProjectRecords';
import { PROJECT_NAME_MAX_LENGTH } from '../types/project-library';
import { errnoCode } from '../utils/errnoCode';

const ProjectRowSchema = z.object({
  id: z.string().uuid(),
  workspaceId: z.string().uuid(),
  name: z.string(),
  projectPath: z.string(),
  createdAt: z.string(),
  lastOpenedAt: z.string(),
  storageKind: z.enum(['project', 'bundle']),
  sourceFingerprint: z.string().nullable(),
  removedAt: z.string().nullable(),
  pinnedAt: z.string().nullable(),
});

export const ProjectNameSchema = z
  .string()
  .trim()
  .min(1)
  .max(PROJECT_NAME_MAX_LENGTH);

export interface RegisteredProject extends z.infer<typeof ProjectRowSchema> {
  isAvailable: boolean;
}

interface LibraryRootOptions {
  homeDirectory?: string;
  channel: 'local' | 'production';
}

export const libraryRoot = ({
  homeDirectory = os.homedir(),
  channel,
}: LibraryRootOptions): string =>
  path.join(homeDirectory, '.rivet', 'library', channel);

const canonicalDirectory = (projectPath: string): string => {
  const canonical = fs.realpathSync(projectPath);
  if (!fs.statSync(canonical).isDirectory())
    throw new Error('A project must be a directory');
  return canonical;
};

const decodeProject = (row: unknown): RegisteredProject => {
  const project = ProjectRowSchema.parse(row);
  let isAvailable = false;
  try {
    isAvailable = fs.statSync(project.projectPath).isDirectory();
  } catch (error) {
    const code = errnoCode(error);
    if (code !== 'ENOENT' && code !== 'EACCES' && code !== 'ENOTDIR')
      throw error;
  }
  return { ...project, isAvailable };
};

export class ProjectRegistry {
  private constructor(
    readonly root: string,
    private readonly records: ProjectRecords,
  ) {}

  static async open(root: string): Promise<ProjectRegistry> {
    return new ProjectRegistry(
      path.resolve(root),
      await ProjectRecords.open(root),
    );
  }

  static openReadOnly(root: string): ProjectRegistry | null {
    const records = ProjectRecords.openReadOnly(root);
    return records ? new ProjectRegistry(path.resolve(root), records) : null;
  }

  register({
    projectPath,
    name,
    isExplicitOpen = false,
  }: {
    projectPath: string;
    name?: string;
    isExplicitOpen?: boolean;
  }): RegisteredProject {
    const canonical = canonicalDirectory(projectPath);
    return this.records.transaction(() => {
      const owner = this.findByPath(canonical);
      if (owner) {
        this.records.recordOpening(owner.id, new Date().toISOString());
        if (isExplicitOpen) this.records.restore(owner.id);
        return this.get(owner.id);
      }
      const now = new Date().toISOString();
      const id = randomUUID();
      this.records.insert({
        id,
        name: name ?? path.basename(canonical),
        workspaceId: randomUUID(),
        canonicalPath: canonical,
        createdAt: now,
      });
      return this.get(id);
    });
  }

  list(): RegisteredProject[] {
    return this.records.list().map(decodeProject);
  }

  rename({
    projectId,
    name,
  }: {
    projectId: string;
    name: string;
  }): RegisteredProject {
    const displayName = ProjectNameSchema.parse(name);
    this.get(projectId);
    this.records.rename(projectId, displayName);
    return this.get(projectId);
  }

  setPinned({
    projectId,
    isPinned,
  }: {
    projectId: string;
    isPinned: boolean;
  }): RegisteredProject {
    this.get(projectId);
    this.records.setPinned({ projectId, isPinned });
    return this.get(projectId);
  }

  remove(projectId: string): void {
    this.get(projectId);
    this.records.remove(projectId);
  }

  get(projectId: string): RegisteredProject {
    const row = this.records.get(projectId);
    if (!row)
      throw new LibraryError(
        'project_not_found',
        `Unknown project: ${projectId}`,
      );
    return decodeProject(row);
  }

  findByPath(projectPath: string): RegisteredProject | null {
    let canonical = path.resolve(projectPath);
    try {
      canonical = fs.realpathSync(canonical);
    } catch (error) {
      if (errnoCode(error) !== 'ENOENT') throw error;
    }
    const row = this.records.findByPath(canonical);
    return row ? decodeProject(row) : null;
  }

  attachHistoryRoot({
    projectId,
    projectPath,
  }: {
    projectId: string;
    projectPath: string;
  }): void {
    const canonical = canonicalDirectory(projectPath);
    this.records.transaction(() => {
      this.get(projectId);
      const existing = this.findByPath(canonical);
      if (existing && existing.id !== projectId)
        throw new Error('History root belongs to another project');
      this.records.attachHistoryRoot(projectId, canonical);
    });
  }

  historyRoots(projectId: string): string[] {
    const project = this.get(projectId);
    const aliases = this.records.historyRoots(projectId);
    return Array.from(new Set([project.projectPath, ...aliases]));
  }

  relink({
    projectId,
    projectPath,
  }: {
    projectId: string;
    projectPath: string;
  }): RegisteredProject {
    const canonical = canonicalDirectory(projectPath);
    return this.records.transaction(() => {
      this.get(projectId);
      this.records.relink(projectId, canonical);
      return this.get(projectId);
    });
  }

  activateBundle({
    projectId,
    sourceFingerprint,
  }: {
    projectId: string;
    sourceFingerprint: string | null;
  }): RegisteredProject {
    this.get(projectId);
    this.records.activateBundle(projectId, sourceFingerprint);
    return this.get(projectId);
  }

  bundleDirectory(projectId: string): string {
    return path.join(this.root, 'projects', this.get(projectId).id);
  }

  close(): void {
    this.records.close();
  }
}
